class SparseMatrix {
    private ArrayList<int[]> entries = new ArrayList<>();

    void set(int r, int c, int v) { entries.add(new int[]{r, c, v}); }

    int get(int r, int c) {
        for (int[] e : entries) if (e[0] == r && e[1] == c) return e[2];
        return 0;
    }

    List<Integer> getRow(int r) {
        List<Integer> result = new ArrayList<>();
        for (int[] e : entries) if (e[0] == r) result.add(e[2]);
        return result;
    }
}

