static ArrayList<Object[]> encode(String input) {
    ArrayList<Object[]> result = new ArrayList<>();
    int i = 0;
    while (i < input.length()) {
        char c = input.charAt(i);
        int count = 0;
        while (i < input.length() && input.charAt(i) == c) { count++; i++; }
        result.add(new Object[]{c, count});
    }
    return result;
}

static String decode(ArrayList<Object[]> encoded) {
    StringBuilder sb = new StringBuilder();
    for (Object[] pair : encoded) {
        char c = (char) pair[0];
        int count = (int) pair[1];
        for (int i = 0; i < count; i++) sb.append(c);
    }
    return sb.toString();
}

