interface EventListener { void onEvent(String event); }

class EventBus {
    private ArrayList<EventListener> listeners = new ArrayList<>();
    void addEventListener(EventListener l) { listeners.add(l); }
    void removeEventListener(EventListener l) { listeners.remove(l); }
    void emit(String event) { for (EventListener l : listeners) l.onEvent(event); }
}

