class VersionHistory<T> {
    private ArrayList<T> history = new ArrayList<>();
    private int currentIndex = -1;

    void save(T value) {
        while (history.size() > currentIndex + 1) history.remove(history.size() - 1);
        history.add(value);
        currentIndex++;
    }

    T undo() {
        if (currentIndex > 0) currentIndex--;
        return history.get(currentIndex);
    }

    T redo() {
        if (currentIndex < history.size() - 1) currentIndex++;
        return history.get(currentIndex);
    }

    ArrayList<T> getHistory() { return history; }
}

