class MultiMap<K, V> {
    private ArrayList<Object[]> entries = new ArrayList<>();

    void put(K key, V value) { entries.add(new Object[]{key, value}); }

    List<V> getAll(K key) {
        List<V> result = new ArrayList<>();
        for (Object[] e : entries) if (e[0].equals(key)) result.add((V) e[1]);
        return result;
    }

    void remove(K key) { entries.removeIf(e -> e[0].equals(key)); }

    int size() { return entries.size(); }
}

