static ArrayList<int[]> twoSum(ArrayList<Integer> list, int target) {
    ArrayList<int[]> result = new ArrayList<>();
    for (int i = 0; i < list.size(); i++) {
        for (int j = i + 1; j < list.size(); j++) {
            if (list.get(i) + list.get(j) == target) result.add(new int[]{i, j});
        }
    }
    return result;
}

