class CircularBuffer<T> {
    private ArrayList<T> buffer = new ArrayList<>();
    private int capacity;

    CircularBuffer(int capacity) { this.capacity = capacity; }

    void add(T item) {
        if (buffer.size() >= capacity) buffer.remove(0);
        buffer.add(item);
    }

    int size() { return buffer.size(); }
    boolean isFull() { return buffer.size() == capacity; }
    T get(int index) { return buffer.get(index); }
    List<T> toList() { return new ArrayList<>(buffer); }
}

